-- Blind bin/lot counts with independent recount/review; economic posting stays in 014.
CREATE TABLE inventory.bin_counts(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),warehouse_id uuid NOT NULL,state text NOT NULL DEFAULT 'OPEN'CHECK(state IN('OPEN','SUBMITTED','RECOUNT','RECOUNT_SUBMITTED','APPROVED','POSTED','CANCELLED')),version bigint NOT NULL DEFAULT 1,current_round int NOT NULL DEFAULT 1 CHECK(current_round BETWEEN 1 AND 5),final_skus jsonb,approved_by uuid REFERENCES identity.users(id),created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,id)REFERENCES inventory.counts(company_id,id),FOREIGN KEY(company_id,warehouse_id)REFERENCES catalog.warehouses(company_id,id));
CREATE TABLE inventory.bin_count_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,count_id uuid NOT NULL,position_id uuid NOT NULL,stock_balance_id uuid NOT NULL,product_id uuid NOT NULL,snapshot_quantity numeric(20,6)NOT NULL,snapshot_version bigint NOT NULL,snapshot_picked numeric(20,6)NOT NULL,bin_version bigint NOT NULL,snapshot jsonb NOT NULL,UNIQUE(company_id,id),UNIQUE(company_id,count_id,position_id),FOREIGN KEY(company_id,count_id)REFERENCES inventory.bin_counts(company_id,id),FOREIGN KEY(company_id,position_id)REFERENCES inventory.positions(company_id,id));
CREATE TABLE inventory.bin_count_rounds(company_id uuid NOT NULL,count_id uuid NOT NULL,round_no int NOT NULL CHECK(round_no BETWEEN 1 AND 5),counter_id uuid NOT NULL REFERENCES identity.users(id),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,count_id,round_no),FOREIGN KEY(company_id,count_id)REFERENCES inventory.bin_counts(company_id,id));
CREATE TABLE inventory.bin_count_readings(company_id uuid NOT NULL,count_id uuid NOT NULL,round_no int NOT NULL,line_id uuid NOT NULL,quantity numeric(20,6)NOT NULL CHECK(quantity>=0),created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,count_id,round_no,line_id),FOREIGN KEY(company_id,count_id,round_no)REFERENCES inventory.bin_count_rounds(company_id,count_id,round_no),FOREIGN KEY(company_id,line_id)REFERENCES inventory.bin_count_lines(company_id,id));
CREATE TABLE inventory.bin_count_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,count_id uuid NOT NULL,round_no int NOT NULL,kind text NOT NULL CHECK(kind IN('RECOUNT','APPROVE','POST','CANCEL')),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,count_id)REFERENCES inventory.bin_counts(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bin_counts','bin_count_lines','bin_count_rounds','bin_count_readings','bin_count_decisions']LOOP EXECUTE format('ALTER TABLE inventory.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE inventory.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON inventory.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t<>'bin_counts'THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON inventory.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END$$;
CREATE TRIGGER bin_count_version BEFORE UPDATE ON inventory.bin_counts FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE INDEX ON inventory.bin_counts(company_id,warehouse_id,state,created_at,id);
CREATE INDEX ON inventory.bin_count_lines(company_id,count_id);
INSERT INTO identity.permissions(code,description)VALUES('inventory.bin_counts.read','Read assigned blind bin counts'),('inventory.bin_counts.capture','Capture assigned blind counts'),('inventory.bin_counts.review','Company financial review and independent recount assignment'),('inventory.bin_counts.post','Post approved physical bin count');
CREATE FUNCTION identity.seed_bin_count_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','WAREHOUSE')AND p.code IN('inventory.bin_counts.read','inventory.bin_counts.capture'))OR(r.code='FINANCE'AND p.code='inventory.bin_counts.read')OR(r.code IN('ADMIN','FINANCE')AND p.code IN('inventory.bin_counts.review','inventory.bin_counts.post')))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_bin_count_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION inventory.is_bin_count(p_id uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT EXISTS(SELECT 1 FROM inventory.bin_counts WHERE company_id=core.current_company()AND id=p_id)$$;
CREATE FUNCTION inventory.can_review_bins()RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT count(DISTINCT rp.permission_code)=3 FROM identity.memberships m JOIN identity.users u ON u.id=m.user_id AND u.active JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active AND rp.permission_code IN('inventory.bin_counts.review','inventory.cost.read','inventory.control.read')$$;
CREATE FUNCTION inventory.require_bin_review()RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT inventory.can_review_bins()THEN RAISE EXCEPTION 'Independent financial count review permission required' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION inventory.require_bin_actor(p_count uuid,p_action text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE s inventory.bin_counts;BEGIN SELECT*INTO s FROM inventory.bin_counts WHERE company_id=core.current_company()AND id=p_count;IF NOT FOUND THEN RAISE EXCEPTION 'Bin count unavailable' USING ERRCODE='HT404';END IF;
 IF p_action IN('REVIEW','POST')THEN PERFORM inventory.require_bin_review();IF EXISTS(SELECT 1 FROM inventory.bin_count_rounds WHERE company_id=s.company_id AND count_id=s.id AND counter_id=core.current_actor())THEN RAISE EXCEPTION 'A counter cannot financially review or post their own sheet' USING ERRCODE='42501';END IF;IF p_action='POST'THEN PERFORM inventory.require_control_permission('inventory.bin_counts.post');PERFORM inventory.require_control_permission('inventory.counts.post');END IF;
 ELSE IF p_action IN('READ','CANCEL')AND inventory.can_review_bins()THEN RETURN;END IF;PERFORM inventory.require_access('inventory.bin_counts.read',s.warehouse_id);PERFORM inventory.require_access(CASE WHEN p_action='READ'THEN'inventory.bin_counts.read'ELSE'inventory.bin_counts.capture'END,s.warehouse_id);
 IF p_action='CANCEL'AND s.created_by<>core.current_actor()THEN RAISE EXCEPTION 'Only creator or reviewer may cancel' USING ERRCODE='42501';END IF;IF p_action='CAPTURE'AND NOT EXISTS(SELECT 1 FROM inventory.bin_count_rounds WHERE company_id=s.company_id AND count_id=s.id AND round_no=s.current_round AND counter_id=core.current_actor())THEN RAISE EXCEPTION 'Only the assigned round counter may submit' USING ERRCODE='42501';END IF;END IF;END$$;
CREATE FUNCTION inventory.snapshot_bin_line(p_count uuid,p_pos uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 INSERT INTO inventory.bin_count_lines(company_id,count_id,position_id,stock_balance_id,product_id,snapshot_quantity,snapshot_version,snapshot_picked,bin_version,snapshot)
 SELECT p.company_id,p_count,p.id,b.id,b.product_id,p.quantity,p.version,inventory.position_reserved(p.id),bn.version,jsonb_build_object('binId',bn.id,'binCode',bn.code,'lotId',l.id,'lotCode',l.code,'sku',pr.sku,'name',pr.name,'baseUomId',pr.base_uom_id)FROM inventory.positions p JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.id=p.stock_balance_id JOIN inventory.bins bn ON bn.company_id=p.company_id AND bn.id=p.bin_id JOIN inventory.lots l ON l.company_id=p.company_id AND l.id=p.lot_id JOIN catalog.products pr ON pr.company_id=b.company_id AND pr.id=b.product_id WHERE p.company_id=core.current_company()AND p.id=p_pos;
END$$;
CREATE FUNCTION inventory.start_bin_count(p_wh uuid,p_reference text,p_reason text,p_products uuid[])RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$#variable_conflict use_variable
DECLARE c uuid:=core.current_company();id uuid;p record;BEGIN
 PERFORM inventory.require_access('inventory.bin_counts.read',p_wh);PERFORM inventory.require_access('inventory.bin_counts.capture',p_wh);PERFORM accounting.bas_lock(c,false);id:=inventory.start_count(p_wh,p_reference,p_reason,p_products);
 PERFORM inventory.ensure_unassigned(cl.stock_balance_id)FROM inventory.count_lines cl WHERE cl.company_id=c AND cl.count_id=id;
 INSERT INTO inventory.bin_counts(id,company_id,warehouse_id,created_by)VALUES(id,c,p_wh,core.current_actor());INSERT INTO inventory.bin_count_rounds(company_id,count_id,round_no,counter_id,reason,created_by)VALUES(c,id,1,core.current_actor(),p_reason,core.current_actor());
 FOR p IN SELECT ps.id FROM inventory.positions ps JOIN inventory.count_lines cl ON cl.company_id=ps.company_id AND cl.stock_balance_id=ps.stock_balance_id WHERE cl.company_id=c AND cl.count_id=id ORDER BY ps.id LOOP PERFORM inventory.snapshot_bin_line(id,p.id);END LOOP;
 IF(SELECT count(*)FROM inventory.bin_count_lines WHERE company_id=c AND count_id=id)>500 THEN RAISE EXCEPTION 'At most 500 positions; narrow product selection' USING ERRCODE='HI422';END IF;RETURN id;
END$$;
CREATE FUNCTION inventory.check_bin_snapshot(p_id uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;products uuid[];BEGIN
 SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id;SELECT array_agg(product_id ORDER BY product_id)INTO products FROM inventory.count_lines WHERE company_id=c AND count_id=p_id;
 PERFORM inventory.lock_control_balances(ARRAY[s.warehouse_id],products,p_id);
 PERFORM 1 FROM inventory.positions p JOIN inventory.count_lines l ON l.company_id=p.company_id AND l.stock_balance_id=p.stock_balance_id WHERE l.company_id=c AND l.count_id=p_id ORDER BY p.id FOR UPDATE OF p;
 IF EXISTS(SELECT 1 FROM inventory.count_lines l JOIN inventory.stock_balances b ON b.company_id=l.company_id AND b.id=l.stock_balance_id JOIN inventory.stock_values v ON v.company_id=b.company_id AND v.stock_balance_id=b.id WHERE l.company_id=c AND l.count_id=p_id AND(b.revision,b.on_hand,b.reserved,v.value)IS DISTINCT FROM(l.snapshot_revision,l.snapshot_quantity,l.snapshot_reserved,l.snapshot_value))OR EXISTS(SELECT 1 FROM inventory.bin_count_lines l JOIN inventory.positions p ON p.company_id=l.company_id AND p.id=l.position_id JOIN inventory.bins bn ON bn.company_id=p.company_id AND bn.id=p.bin_id WHERE l.company_id=c AND l.count_id=p_id AND(p.quantity,p.version,inventory.position_reserved(p.id),bn.version)IS DISTINCT FROM(l.snapshot_quantity,l.snapshot_version,l.snapshot_picked,l.bin_version))OR EXISTS(SELECT 1 FROM inventory.positions p JOIN inventory.count_lines l ON l.company_id=p.company_id AND l.stock_balance_id=p.stock_balance_id WHERE l.company_id=c AND l.count_id=p_id AND NOT EXISTS(SELECT 1 FROM inventory.bin_count_lines x WHERE x.company_id=c AND x.count_id=p_id AND x.position_id=p.id))THEN RAISE EXCEPTION 'Stock/reservation/value or bin position changed; cancel and restart count' USING ERRCODE='HI409';END IF;
END$$;
CREATE FUNCTION inventory.discover_bin_count_position(p_id uuid,p_version bigint,p_product uuid,p_bin uuid,p_lot text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;bid uuid;lot uuid;pos uuid;BEGIN
 PERFORM inventory.require_bin_actor(p_id,'CAPTURE');PERFORM accounting.bas_lock(c,false);PERFORM 1 FROM platform.documents WHERE company_id=c AND id=p_id FOR UPDATE;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version OR s.state<>'OPEN'THEN RAISE EXCEPTION 'Discover positions before first submission only' USING ERRCODE='HI409';END IF;PERFORM inventory.check_bin_snapshot(p_id);
 SELECT stock_balance_id INTO bid FROM inventory.count_lines WHERE company_id=c AND count_id=p_id AND product_id=p_product;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM inventory.bins WHERE company_id=c AND id=p_bin AND warehouse_id=s.warehouse_id AND active)OR coalesce(length(btrim(p_lot)),0)NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'Selected SKU, active warehouse bin and lot required' USING ERRCODE='HI422';END IF;
 INSERT INTO inventory.lots(company_id,product_id,code)VALUES(c,p_product,btrim(p_lot))ON CONFLICT DO NOTHING;SELECT id INTO lot FROM inventory.lots WHERE company_id=c AND product_id=p_product AND code=btrim(p_lot);
 INSERT INTO inventory.positions(company_id,stock_balance_id,bin_id,lot_id,quantity)VALUES(c,bid,p_bin,lot,0)ON CONFLICT DO NOTHING;SELECT id INTO pos FROM inventory.positions WHERE company_id=c AND stock_balance_id=bid AND bin_id=p_bin AND lot_id=lot;
 IF EXISTS(SELECT 1 FROM inventory.bin_count_lines WHERE company_id=c AND count_id=p_id AND position_id=pos)THEN RAISE EXCEPTION 'Position already in sheet' USING ERRCODE='HI409';END IF;
 IF(SELECT count(*)FROM inventory.bin_count_lines WHERE company_id=c AND count_id=p_id)>=500 THEN RAISE EXCEPTION 'Position limit exceeded' USING ERRCODE='HI422';END IF;PERFORM inventory.snapshot_bin_line(p_id,pos);UPDATE inventory.bin_counts SET state=state WHERE company_id=c AND id=p_id;RETURN pos;
END$$;
CREATE FUNCTION inventory.submit_bin_count(p_id uuid,p_version bigint,p_items jsonb)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;x jsonb;qty numeric;BEGIN
 PERFORM inventory.require_bin_actor(p_id,'CAPTURE');PERFORM accounting.bas_lock(c,false);PERFORM 1 FROM platform.documents WHERE company_id=c AND id=p_id FOR UPDATE;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version OR s.state NOT IN('OPEN','RECOUNT')THEN RAISE EXCEPTION 'Current open round required' USING ERRCODE='HI409';END IF;
 IF p_items IS NULL OR jsonb_typeof(p_items)<>'array'OR jsonb_array_length(p_items)<>(SELECT count(*)FROM inventory.bin_count_lines WHERE company_id=c AND count_id=p_id)OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_items)item GROUP BY item->>'lineId'HAVING count(*)>1)THEN RAISE EXCEPTION 'Count every sheet line exactly once, including explicit zero' USING ERRCODE='HI422';END IF;
 FOR x IN SELECT*FROM jsonb_array_elements(p_items)LOOP qty:=(x->>'quantity')::numeric;IF qty IS NULL OR qty<0 OR qty<>round(qty,6)OR qty>99999999999999.999999 OR NOT EXISTS(SELECT 1 FROM inventory.bin_count_lines WHERE company_id=c AND count_id=p_id AND id=(x->>'lineId')::uuid)THEN RAISE EXCEPTION 'Invalid line or counted base quantity' USING ERRCODE='HI422';END IF;
 INSERT INTO inventory.bin_count_readings(company_id,count_id,round_no,line_id,quantity,created_by)VALUES(c,p_id,s.current_round,(x->>'lineId')::uuid,qty,core.current_actor());END LOOP;
 UPDATE inventory.bin_counts SET state=CASE WHEN current_round=1 THEN'SUBMITTED'ELSE'RECOUNT_SUBMITTED'END WHERE company_id=c AND id=p_id;
END$$;
CREATE FUNCTION inventory.review_bin_count(p_id uuid,p_version bigint,p_action text,p_reason text,p_counter uuid DEFAULT NULL,p_values jsonb DEFAULT '[]')RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;final jsonb;BEGIN
 PERFORM inventory.require_bin_actor(p_id,'REVIEW');PERFORM accounting.bas_lock(c,false);PERFORM 1 FROM platform.documents WHERE company_id=c AND id=p_id FOR UPDATE;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version OR s.state NOT IN('SUBMITTED','RECOUNT_SUBMITTED')OR p_action IS NULL OR p_action NOT IN('RECOUNT','APPROVE')OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Current submitted round and review reason required' USING ERRCODE='HI409';END IF;
 IF p_action='RECOUNT'THEN
 IF s.current_round>=5 OR p_counter IS NULL OR p_counter=s.created_by OR NOT EXISTS(SELECT 1 FROM identity.memberships m JOIN identity.users u ON u.id=m.user_id AND u.active JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=c AND m.user_id=p_counter AND m.active AND rp.permission_code='inventory.bin_counts.capture'AND(EXISTS(SELECT 1 FROM identity.role_permissions p WHERE p.company_id=m.company_id AND p.role_id=mr.role_id AND p.permission_code='warehouses.all')OR EXISTS(SELECT 1 FROM identity.warehouse_scopes w WHERE w.company_id=m.company_id AND w.membership_id=m.id AND w.warehouse_id=s.warehouse_id)))THEN RAISE EXCEPTION 'Assign a different active counter with warehouse capture access (max five rounds)' USING ERRCODE='HI422';END IF;
 INSERT INTO inventory.bin_count_rounds(company_id,count_id,round_no,counter_id,reason,created_by)VALUES(c,p_id,s.current_round+1,p_counter,btrim(p_reason),core.current_actor());UPDATE inventory.bin_counts SET current_round=current_round+1,state='RECOUNT'WHERE company_id=c AND id=p_id;
 ELSE
 IF EXISTS(SELECT 1 FROM inventory.bin_count_rounds WHERE company_id=c AND count_id=p_id AND counter_id=core.current_actor())THEN RAISE EXCEPTION 'A counter cannot approve their own sheet' USING ERRCODE='42501';END IF;
 IF s.current_round=1 AND EXISTS(SELECT 1 FROM inventory.bin_count_lines l JOIN inventory.bin_count_readings r ON r.company_id=l.company_id AND r.line_id=l.id AND r.count_id=l.count_id AND r.round_no=1 WHERE l.company_id=c AND l.count_id=p_id AND r.quantity<>l.snapshot_quantity)THEN RAISE EXCEPTION 'Any bin variance needs an independent blind recount' USING ERRCODE='HI409';END IF;
 PERFORM inventory.check_bin_snapshot(p_id);
 IF p_values IS NULL OR jsonb_typeof(p_values)<>'array'OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_values)e GROUP BY e->>'productId'HAVING count(*)>1)OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_values)e WHERE NOT EXISTS(SELECT 1 FROM inventory.count_lines WHERE company_id=c AND count_id=p_id AND product_id=(e->>'productId')::uuid))THEN RAISE EXCEPTION 'Gain values must name distinct sheet products' USING ERRCODE='HI422';END IF;
 SELECT jsonb_agg(jsonb_build_object('productId',cl.product_id,'countedQuantity',q.qty,'gainValue',(SELECT e->'gainValue'FROM jsonb_array_elements(p_values)e WHERE(e->>'productId')::uuid=cl.product_id))ORDER BY cl.product_id)INTO final FROM inventory.count_lines cl JOIN LATERAL(SELECT sum(r.quantity)AS qty FROM inventory.bin_count_readings r JOIN inventory.bin_count_lines bl ON bl.company_id=r.company_id AND bl.id=r.line_id WHERE r.company_id=c AND r.count_id=p_id AND r.round_no=s.current_round AND bl.product_id=cl.product_id)q ON true WHERE cl.company_id=c AND cl.count_id=p_id;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(final)e JOIN inventory.count_lines cl ON cl.company_id=c AND cl.count_id=p_id AND cl.product_id=(e->>'productId')::uuid WHERE(e->>'countedQuantity')IS NULL OR(e->>'countedQuantity')::numeric>99999999999999.999999 OR(e->>'countedQuantity')::numeric<cl.snapshot_reserved OR(cl.snapshot_quantity>0 OR(e->>'countedQuantity')::numeric=0)AND(e->>'gainValue')IS NOT NULL OR cl.snapshot_quantity=0 AND(e->>'countedQuantity')::numeric>0 AND((e->>'gainValue')IS NULL OR(e->>'gainValue')::numeric<0 OR(e->>'gainValue')::numeric<>round((e->>'gainValue')::numeric,2)))OR EXISTS(SELECT 1 FROM inventory.bin_count_readings r JOIN inventory.bin_count_lines l ON l.company_id=r.company_id AND l.id=r.line_id WHERE r.company_id=c AND r.count_id=p_id AND r.round_no=s.current_round AND r.quantity<l.snapshot_picked)THEN RAISE EXCEPTION 'Cannot consume reserved stock; empty-SKU gains require explicit cents valuation only' USING ERRCODE='HI422';END IF;
 UPDATE inventory.bin_counts SET state='APPROVED',final_skus=final,approved_by=core.current_actor()WHERE company_id=c AND id=p_id;
 END IF;
 INSERT INTO inventory.bin_count_decisions(company_id,count_id,round_no,kind,reason,created_by)VALUES(c,p_id,s.current_round,p_action,btrim(p_reason),core.current_actor());
END$$;
CREATE FUNCTION inventory.post_bin_count(p_id uuid,p_version bigint,p_reason text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;x record;delta numeric;old_pick text:=current_setting('htt.dispatch_pick',true);v bigint;BEGIN
 PERFORM inventory.require_bin_actor(p_id,'POST');PERFORM accounting.bas_lock(c,false);PERFORM 1 FROM platform.documents WHERE company_id=c AND id=p_id FOR UPDATE;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version OR s.state<>'APPROVED'OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Current approved count and posting reason required' USING ERRCODE='HI409';END IF;PERFORM inventory.check_bin_snapshot(p_id);
 SELECT version INTO v FROM platform.documents WHERE company_id=c AND id=p_id;PERFORM inventory.submit_count(p_id,v,s.final_skus);SELECT version INTO v FROM platform.documents WHERE company_id=c AND id=p_id;
 PERFORM set_config('htt.dispatch_pick',p_id::text,true);PERFORM inventory.post_count(p_id,v);PERFORM set_config('htt.dispatch_pick',coalesce(old_pick,''),true);
 FOR x IN SELECT l.position_id,r.quantity FROM inventory.bin_count_lines l JOIN inventory.bin_count_readings r ON r.company_id=l.company_id AND r.count_id=l.count_id AND r.line_id=l.id AND r.round_no=s.current_round WHERE l.company_id=c AND l.count_id=p_id ORDER BY l.position_id LOOP
 SELECT x.quantity-p.quantity INTO delta FROM inventory.positions p WHERE p.company_id=c AND p.id=x.position_id;
 IF delta<>0 THEN UPDATE inventory.positions SET quantity=x.quantity WHERE company_id=c AND id=x.position_id;INSERT INTO inventory.position_movements(company_id,position_id,document_id,quantity,reason,request_id,created_by)VALUES(c,x.position_id,p_id,delta,'BIN_COUNT_APPLIED',current_setting('htt.request_id',true),core.current_actor());END IF;END LOOP;
 UPDATE inventory.bin_counts SET state='POSTED'WHERE company_id=c AND id=p_id;INSERT INTO inventory.bin_count_decisions(company_id,count_id,round_no,kind,reason,created_by)VALUES(c,p_id,s.current_round,'POST',p_reason,core.current_actor());
END$$;
CREATE FUNCTION inventory.cancel_bin_count(p_id uuid,p_version bigint,p_reason text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;v bigint;BEGIN
 PERFORM inventory.require_bin_actor(p_id,'CANCEL');PERFORM accounting.bas_lock(c,false);PERFORM 1 FROM platform.documents WHERE company_id=c AND id=p_id FOR UPDATE;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id FOR UPDATE;
 IF NOT inventory.can_review_bins()AND s.created_by<>core.current_actor()THEN RAISE EXCEPTION 'Creator or financial reviewer may cancel' USING ERRCODE='42501';END IF;
 IF s.version IS DISTINCT FROM p_version OR s.state IN('POSTED','CANCELLED')OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Current unposted sheet and reason required' USING ERRCODE='HI409';END IF;
 UPDATE inventory.bin_counts SET state='CANCELLED'WHERE company_id=c AND id=p_id;SELECT version INTO v FROM platform.documents WHERE company_id=c AND id=p_id;
 -- Base cancellation is guarded by scope; reviewers use the same registered cancellation transition here.
 UPDATE inventory.counts SET state='CANCELLED'WHERE company_id=c AND id=p_id;UPDATE platform.documents SET state='CANCELLED'WHERE company_id=c AND id=p_id;
 INSERT INTO inventory.bin_count_decisions(company_id,count_id,round_no,kind,reason,created_by)VALUES(c,p_id,s.current_round,'CANCEL',p_reason,core.current_actor());
END$$;
CREATE FUNCTION inventory.bin_count_view(p_id uuid,p_financial boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();s inventory.bin_counts;review boolean:=inventory.can_review_bins();BEGIN
 PERFORM inventory.require_bin_actor(p_id,'READ');IF p_financial THEN PERFORM inventory.require_bin_actor(p_id,'REVIEW');END IF;review:=review AND NOT EXISTS(SELECT 1 FROM inventory.bin_count_rounds WHERE company_id=c AND count_id=p_id AND counter_id=core.current_actor());SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=p_id;
 RETURN jsonb_build_object('id',s.id,'warehouseId',s.warehouse_id,'state',s.state,'version',s.version,'currentRound',s.current_round,'number',(SELECT number FROM platform.documents WHERE company_id=c AND id=p_id),'reference',(SELECT reference FROM inventory.counts WHERE company_id=c AND id=p_id),'cutoffAt',s.created_at,'createdBy',s.created_by,'createdAt',s.created_at,'blind',NOT review,'counterId',(SELECT counter_id FROM inventory.bin_count_rounds WHERE company_id=c AND count_id=p_id AND round_no=s.current_round),'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'positionId',l.position_id,'productId',l.product_id,'snapshot',l.snapshot)||CASE WHEN review THEN jsonb_build_object('expectedQuantity',l.snapshot_quantity::text,'pickedReserved',l.snapshot_picked::text)ELSE'{}'::jsonb END||jsonb_build_object('readings',coalesce((SELECT jsonb_agg(jsonb_build_object('round',r.round_no,'quantity',r.quantity::text)ORDER BY r.round_no)FROM inventory.bin_count_readings r WHERE r.company_id=c AND r.line_id=l.id AND(review OR r.created_by=core.current_actor())),'[]'))ORDER BY l.id)FROM inventory.bin_count_lines l WHERE l.company_id=c AND l.count_id=p_id),'[]'),'financial',CASE WHEN review THEN(SELECT jsonb_agg(jsonb_build_object('productId',cl.product_id,'snapshotQuantity',cl.snapshot_quantity::text,'snapshotReserved',cl.snapshot_reserved::text,'snapshotValue',cl.snapshot_value::text,'snapshotRevision',cl.snapshot_revision)ORDER BY cl.product_id)FROM inventory.count_lines cl WHERE cl.company_id=c AND cl.count_id=p_id)ELSE NULL END,'valuation',CASE WHEN review THEN s.final_skus ELSE NULL END,'decisions',CASE WHEN review THEN coalesce((SELECT jsonb_agg(jsonb_build_object('kind',kind,'round',round_no,'reason',reason,'actorId',created_by,'createdAt',created_at)ORDER BY created_at,id)FROM inventory.bin_count_decisions WHERE company_id=c AND count_id=p_id),'[]')ELSE'[]'::jsonb END);
END$$;
-- Old direct total-count commands cannot bypass position reconciliation/review.
CREATE FUNCTION inventory.guard_bin_base()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s inventory.bin_counts;expected jsonb;BEGIN
 SELECT*INTO s FROM inventory.bin_counts WHERE company_id=OLD.company_id AND id=coalesce(to_jsonb(OLD)->>'count_id',to_jsonb(OLD)->>'id')::uuid;IF NOT FOUND THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='counts'THEN IF NEW.state='SUBMITTED'AND s.state<>'APPROVED'OR NEW.state='POSTED'AND s.state<>'APPROVED'OR NEW.state='CANCELLED'AND s.state<>'CANCELLED'THEN RAISE EXCEPTION 'Use reviewed bin-count workflow' USING ERRCODE='HI409';END IF;
 ELSE SELECT e INTO expected FROM jsonb_array_elements(s.final_skus)e WHERE(e->>'productId')::uuid=OLD.product_id;IF s.state<>'APPROVED'OR expected IS NULL OR NEW.counted_quantity IS DISTINCT FROM(expected->>'countedQuantity')::numeric OR NEW.gain_value IS DISTINCT FROM(expected->>'gainValue')::numeric THEN RAISE EXCEPTION 'Only approved SKU totals may enter base count' USING ERRCODE='HI409';END IF;END IF;RETURN NEW;
END$$;
CREATE TRIGGER bin_base_guard BEFORE UPDATE ON inventory.counts FOR EACH ROW EXECUTE FUNCTION inventory.guard_bin_base();
CREATE TRIGGER bin_base_guard BEFORE UPDATE ON inventory.count_lines FOR EACH ROW EXECUTE FUNCTION inventory.guard_bin_base();
CREATE FUNCTION inventory.validate_bin_count()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c uuid:=NEW.company_id;cid uuid; s inventory.bin_counts;bs text;BEGIN
 cid:=coalesce(to_jsonb(NEW)->>'count_id',to_jsonb(NEW)->>'id')::uuid;SELECT*INTO s FROM inventory.bin_counts WHERE company_id=c AND id=cid;IF NOT FOUND THEN RETURN NULL;END IF;SELECT state INTO bs FROM inventory.counts WHERE company_id=c AND id=cid;
 IF(s.state='POSTED')IS DISTINCT FROM(bs='POSTED')OR(s.state='CANCELLED')IS DISTINCT FROM(bs='CANCELLED')OR s.state NOT IN('POSTED','CANCELLED')AND bs<>'OPEN'OR NOT EXISTS(SELECT 1 FROM inventory.bin_count_lines WHERE company_id=c AND count_id=cid)THEN RAISE EXCEPTION 'Bin/base count states or source lines disagree' USING ERRCODE='23514';END IF;
 IF s.state='POSTED'AND EXISTS(SELECT 1 FROM inventory.bin_count_lines l JOIN inventory.positions p ON p.company_id=l.company_id AND p.id=l.position_id JOIN inventory.bin_count_readings r ON r.company_id=l.company_id AND r.count_id=l.count_id AND r.line_id=l.id AND r.round_no=s.current_round WHERE l.company_id=c AND l.count_id=cid AND p.quantity<>r.quantity)THEN RAISE EXCEPTION 'Posted positions differ from approved blind count' USING ERRCODE='23514';END IF;RETURN NULL;
END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bin_counts','bin_count_lines','bin_count_readings','counts','count_lines']LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER bin_count_proof AFTER INSERT OR UPDATE ON inventory.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION inventory.validate_bin_count()',t);END LOOP;END$$;

CREATE OR REPLACE FUNCTION inventory.submit_count(p_count uuid,p_expected bigint,items jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();sheet inventory.counts;doc platform.documents;entry jsonb;qty numeric;gv numeric;BEGIN
 SELECT * INTO sheet FROM inventory.counts WHERE company_id=c AND id=p_count;IF NOT FOUND THEN RAISE EXCEPTION 'Count unavailable' USING ERRCODE='HT404';END IF;IF inventory.is_bin_count(p_count)THEN PERFORM inventory.require_bin_actor(p_count,'POST');ELSE PERFORM inventory.require_access('inventory.counts.write',sheet.warehouse_id);END IF;
 SELECT * INTO doc FROM platform.documents WHERE company_id=c AND id=p_count FOR UPDATE;SELECT * INTO sheet FROM inventory.counts WHERE company_id=c AND id=p_count;
 IF doc.version IS DISTINCT FROM p_expected OR sheet.state<>'OPEN' THEN RAISE EXCEPTION 'Only current open count can be submitted' USING ERRCODE='HI409';END IF;
 IF items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items)<>(SELECT count(*) FROM inventory.count_lines WHERE company_id=c AND count_id=p_count) OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)x GROUP BY x->>'productId' HAVING count(*)>1) THEN RAISE EXCEPTION 'Supply every count product exactly once' USING ERRCODE='HI422';END IF;
 FOR entry IN SELECT * FROM jsonb_array_elements(items) LOOP
 qty:=(entry->>'countedQuantity')::numeric;gv:=(entry->>'gainValue')::numeric;
 IF qty IS NULL OR qty<0 OR qty<>round(qty,6) OR qty>99999999999999.999999 OR (gv IS NOT NULL AND(gv<0 OR gv<>round(gv,2) OR gv>999999999999999999.99)) THEN RAISE EXCEPTION 'Invalid counted base quantity or gain value' USING ERRCODE='HI422';END IF;
 UPDATE inventory.count_lines SET counted_quantity=qty,gain_value=gv WHERE company_id=c AND count_id=p_count AND product_id=(entry->>'productId')::uuid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Count product unavailable' USING ERRCODE='HT404';END IF;
 END LOOP;
 UPDATE inventory.counts SET state='SUBMITTED' WHERE company_id=c AND id=p_count;UPDATE platform.documents SET state='CONFIRMED' WHERE company_id=c AND id=p_count;
END $$;
CREATE FUNCTION inventory.guard_bin_header()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF TG_OP='DELETE'OR OLD.state IN('POSTED','CANCELLED')OR(to_jsonb(NEW)-ARRAY['state','version','updated_at','current_round','final_skus','approved_by'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','version','updated_at','current_round','final_skus','approved_by'])OR NOT((OLD.state='OPEN'AND NEW.state IN('OPEN','SUBMITTED','CANCELLED'))OR(OLD.state IN('SUBMITTED','RECOUNT_SUBMITTED')AND NEW.state IN('RECOUNT','APPROVED','CANCELLED'))OR(OLD.state='RECOUNT'AND NEW.state IN('RECOUNT_SUBMITTED','CANCELLED'))OR(OLD.state='APPROVED'AND NEW.state IN('POSTED','CANCELLED')))THEN RAISE EXCEPTION 'Invalid/final blind count mutation' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER bin_count_guard BEFORE UPDATE OR DELETE ON inventory.bin_counts FOR EACH ROW EXECUTE FUNCTION inventory.guard_bin_header();
GRANT SELECT ON inventory.bin_counts,inventory.bin_count_lines,inventory.bin_count_rounds,inventory.bin_count_readings,inventory.bin_count_decisions TO htt_app;
DO $$DECLARE r regprocedure;BEGIN FOR r IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('identity','inventory')AND p.proname=ANY(ARRAY['seed_bin_count_roles','is_bin_count','can_review_bins','require_bin_review','require_bin_actor','snapshot_bin_line','start_bin_count','check_bin_snapshot','discover_bin_count_position','submit_bin_count','review_bin_count','post_bin_count','cancel_bin_count','bin_count_view','guard_bin_base','validate_bin_count','guard_bin_header'])LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',r);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION inventory.is_bin_count(uuid),inventory.require_bin_actor(uuid,text),inventory.start_bin_count(uuid,text,text,uuid[]),inventory.discover_bin_count_position(uuid,bigint,uuid,uuid,text),inventory.submit_bin_count(uuid,bigint,jsonb),inventory.review_bin_count(uuid,bigint,text,text,uuid,jsonb),inventory.post_bin_count(uuid,bigint,text),inventory.cancel_bin_count(uuid,bigint,text),inventory.bin_count_view(uuid,boolean)TO htt_app;

CREATE FUNCTION inventory.require_bin_list(p_wh uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF inventory.can_review_bins()THEN PERFORM inventory.require_bin_review();ELSE PERFORM inventory.require_access('inventory.bin_counts.read',p_wh);END IF;END$$;
REVOKE ALL ON FUNCTION inventory.require_bin_list(uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION inventory.require_bin_list(uuid)TO htt_app;
